window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b6fe5be31115df2"]={"versions": [{"id": "FIG-8b6fe5be31115df2", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetPeriodAndDuty()</code>) zur Spezifikation des synchronen Funktionsaufrufs zur gemeinsamen Aktualisierung von Periode und Tastverhältnis im AUTOSAR Classic Platform MCAL PWM-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pwm User</strong>: Aufrufende Entität / Software-Komponente der oberen Schichten.</li>\n<li><strong>PWM Driver</strong>: Ziel-Treiberbaustein der Microcontroller Abstraction Layer (MCAL).</li>\n<li><strong>Schnittstelle</strong>: Funktionsaufruf <code>Pwm_SetPeriodAndDuty(ChannelNumber, Period, DutyCycle)</code> mit anschließender Rückkehr (<code>return</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Pwm User</code> setzt einen synchronen Funktionsaufruf <code>Pwm_SetPeriodAndDuty(ChannelNumber, Period, DutyCycle)</code> an den <code>PWM Driver</code> ab.</li>\n<li>Der <code>PWM Driver</code> übernimmt die Parameter zur Ausführung.</li>\n<li>Der <code>PWM Driver</code> quittiert den Aufruf mit einer synchronen Rückkehr (<code>return</code>) an den <code>Pwm User</code>.</li>\n<li>Die Übernahme der geänderten Periode und des Tastverhältnisses erfolgt am Ende der laufenden Periode, sofern konfiguriert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Übergabeparameter benennen die semantischen Bezeichner <code>ChannelNumber</code>, <code>Period</code> und <code>DutyCycle</code>. Die tatsächliche Hardware-Aktualisierung des PWM-Signals ist konfigurierbar und wird erst zum Periodenende wirksam. Die Rückkehr erfolgt synchron ohne Rückgabewert (<code>void</code>).</p>"}, {"id": "FIG-8cbbbaf5c2f9a716", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetPeriodAndDuty()</code>) zur Spezifikation des synchronen Funktionsaufrufs zur gemeinsamen Aktualisierung von Periode und Tastverhältnis im AUTOSAR Classic Platform MCAL PWM-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Generic Elements::Pwm User</strong>: Aufrufende Entität aus dem Modellpaket <code>Generic Elements</code>.</li>\n<li><strong>«module» Pwm::Pwm</strong>: Treiber-Modul der MCAL im Namensraum <code>Pwm</code>, gekennzeichnet mit UML-Modul-Stereotyp und Subsystem-Symbol.</li>\n<li><strong>Schnittstelle</strong>: Synchroner Aufruf <code>Pwm_SetPeriodAndDuty(ChannelNumber,Period,DutyCycle)</code> und Rückkehr <code>Pwm_SetPeriodAndDuty</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Generic Elements::Pwm User</code> sendet den synchronen Aufruf <code>Pwm_SetPeriodAndDuty(ChannelNumber,Period,DutyCycle)</code> an <code>«module» Pwm::Pwm</code>.</li>\n<li>Das Modul aktiviert seinen Ausführungsfokus und antwortet mit der Rückkehrnachricht <code>Pwm_SetPeriodAndDuty</code>.</li>\n<li>Eine strukturierte Notiz dokumentiert den Status <code>proposed by DB as per SWS Pwm Driver 1.0.9</code> sowie das Verhalten zur Perioden- und Tastverhältnisumstellung zum Periodenende bei entsprechender Konfiguration.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Spezifikation führt einen formalen Statusvermerk (<code>Status: proposed by DB as per SWS Pwm Driver 1.0.9</code>) und standardisierte Beschreibungsfelder ein. Die Parameterübergabe verwendet Bezeichner ohne explizite Typangaben; die Rückkehrnachricht trägt den Funktionsnamen.</p>"}, {"id": "FIG-2338458dd4ca7fa5", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Pwm_SetPeriodAndDuty()</code>) zur Spezifikation des synchronen Funktionsaufrufs zur gemeinsamen Aktualisierung von Periode und Tastverhältnis im AUTOSAR Classic Platform MCAL PWM-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Pwm User</strong>: Aufrufende Schicht/Komponente.</li>\n<li><strong>«module» Pwm</strong>: MCAL-Treibermodul (Stereotyp «module» mit Subsystem-Symbol).</li>\n<li><strong>Schnittstelle</strong>: Funktionsaufruf <code>Pwm_SetPeriodAndDuty(Pwm_ChannelType, Pwm_PeriodType, uint16)</code> und synchrone Rückkehr <code>Pwm_SetPeriodAndDuty()</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>Pwm User</code> ruft <code>Pwm_SetPeriodAndDuty(Pwm_ChannelType, Pwm_PeriodType, uint16)</code> auf der Lebenslinie von <code>«module» Pwm</code> auf.</li>\n<li>Das Modul bearbeitet den Aufruf und kehrt synchron mit <code>Pwm_SetPeriodAndDuty()</code> zum Aufrufer zurück.</li>\n<li>Die Änderung der Periode wird gemäß Beschreibung am Ende der aktuellen Signalperiode aktiv, falls dies so konfiguriert ist.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die API-Signatur ist typisiert: Für Kanal und Periode kommen die AUTOSAR-Typen <code>Pwm_ChannelType</code> und <code>Pwm_PeriodType</code> zum Einsatz, während das Tastverhältnis als <code>uint16</code> spezifiziert ist. Dies bindet Aufrufer und Treiber direkt an die normativen C-Datentypen der MCAL-Schnittstelle.</p>"}], "trans": [{"from": "FIG-8b6fe5be31115df2", "to": "FIG-8cbbbaf5c2f9a716", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Lebenslinien/Rollen</strong>: Der Aufrufer wird von <code>Pwm User</code> zu <code>Generic Elements::Pwm User</code> umbenannt. Die Zielkomponente <code>PWM Driver</code> wird durch das Modul <code>«module» Pwm::Pwm</code> mit Subsystem-/Komponentensymbol ersetzt.</li>\n<li><strong>Rückkehrnachricht</strong>: Die Beschriftung des gestrichelten Return-Pfeils ändert sich von <code>return</code> zu <code>Pwm_SetPeriodAndDuty</code>.</li>\n<li><strong>Anmerkungen/Dokumentation</strong>: Die freistehenden Randnotizen („Set PWM signal period and duty cycle“ oben links sowie „The PWM period and duty cycle are changed at the end of the current period if configured“ unten rechts) werden in einem strukturierten Notizblock zusammengefasst mit den Feldern <code>Status</code> (<code>proposed by DB as per SWS Pwm Driver 1.0.9</code>), <code>Description</code> (<code>Set PWM signal period The PWM period is changed at the end of the current period if configured.</code>) und <code>Comments:</code>.</li>\n</ul>"}, {"from": "FIG-8cbbbaf5c2f9a716", "to": "FIG-2338458dd4ca7fa5", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>Aufruf-Signatur</strong>: Beim synchronen Funktionsaufruf werden anstelle der Parameternamen (<code>ChannelNumber,Period,DutyCycle</code>) konkrete AUTOSAR-Datentypen spezifiziert: <code>Pwm_SetPeriodAndDuty(Pwm_ChannelType, Pwm_PeriodType, uint16)</code>.</li>\n<li><strong>Rückkehrnachricht</strong>: Die Beschriftung der Rückkehrantwort erhält Klammern: <code>Pwm_SetPeriodAndDuty()</code>.</li>\n<li><strong>Lebenslinien/Rollen</strong>: Die Paket-Präfixe entfallen; die Lebenslinien lauten wieder <code>Pwm User</code> (statt <code>Generic Elements::Pwm User</code>) und <code>«module» Pwm</code> (statt <code>«module» Pwm::Pwm</code>).</li>\n</ul>"}]};
